### 3. Complete Integration Test Template

The following template from [`tests/api_integration.test.js`](https://github.com/jeremiahjmorris1126-coder/TRUCKWITHEASE-1/blob/main/tests/api_integration.test.js#L1-L86) demonstrates request execution, status assertion, correlation header inspection, and structured body verification:

```javascript
import test from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';

import { createApiApp } from '../server.ts';
import { createFleetCore } from '../server/fleetCore.ts';

// Dynamic port 0 ephemeral server with isolated in-memory dependency injection container
function setupTestServer() {
  const isolatedCore = createFleetCore(); // Fresh DB repositories per instance
  const app = createApiApp(isolatedCore);
  const server = http.createServer(app);

  return new Promise((resolve, reject) => {
    server.listen(0, '127.0.0.1', () => {
      const addr = server.address();
      const baseUrl = `http://127.0.0.1:${addr.port}`;
      resolve({
        server,
        baseUrl,
        isolatedCore,
        close: () => new Promise((res) => server.close(res)),
      });
    });
    server.on('error', reject);
  });
}

test('POST /api/auth/signup -> Integration Test Template', async (t) => {
  const env = await setupTestServer();
  t.after(async () => {
    await env.close();
  });

  // 1. Happy Path: Register Commercial Driver
  await t.test('Happy path creates new driver and issues correlation header', async () => {
    const payload = {
      fullName: 'Marcus Vance',
      cdlNumber: 'CDL-TX-884920',
      fmcsaPin: '7721',
      unitNumber: 'TRK-904',
      email: 'm.vance@freightops.com',
      phone: '+18175551234',
    };

    const res = await fetch(`${env.baseUrl}/api/auth/signup`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });

    // HTTP Status assertion
    assert.equal(res.status, 201);

    // Header assertion (Structured correlation trace ID)
    assert.ok(res.headers.get('x-correlation-id'));

    // Response Body assertion
    const body = await res.json();
    assert.equal(body.success, true);
    assert.equal(body.driver.fullName, 'Marcus Vance');
    assert.equal(body.driver.unitNumber, 'TRK-904');
    assert.equal(body.driver.cdlNumberMasked, 'CD****20'); // PII masked
    assert.equal(body.driver.fmcsaSafetyGrade, 'A+');
  });

  // 2. Validation Error: Missing Required Field
  await t.test('Validation error returns 400 with domain error schema', async () => {
    const invalidPayload = {
      cdlNumber: 'CDL-TX-884920',
      fmcsaPin: '7721',
      // fullName is missing
    };

    const res = await fetch(`${env.baseUrl}/api/auth/signup`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(invalidPayload),
    });

    assert.equal(res.status, 400);

    const body = await res.json();
    assert.equal(body.success, false);
    assert.equal(body.error.code, 'E_DOMAIN_VALIDATION');
    assert.match(body.error.message, /Driver full name is required/i);
  });

  // 3. Auth / Permission Failure: Enforced Carrier Secret
  await t.test('Protected endpoint returns 401 on unauthorized access', async () => {
    const prevSecret = process.env.CARRIER_API_SECRET;
    process.env.CARRIER_API_SECRET = 'SECRET_FLEET_TOKEN_XYZ';

    try {
      const res = await fetch(`${env.baseUrl}/api/export-cloudflare-github/status`);
      assert.equal(res.status, 401);

      const body = await res.json();
      assert.equal(body.error, 'Unauthorized');
      assert.match(body.message, /Carrier API Token or Bearer Authorization required/i);
    } finally {
      if (prevSecret === undefined) {
        delete process.env.CARRIER_API_SECRET;
      } else {
        process.env.CARRIER_API_SECRET = prevSecret;
      }
    }
  });
});
```

